#!/usr/bin/env python3# -*- coding: utf-8 -*-"""H₂ 微洩漏智慧檢測系統 - FastAPI 後端 v5.0（雙感測器 + 新版 runtime pipeline）=========================================================先設 RAW_BUFFER_SEC = 5 秒v5.0 相對 v4.0（two_sensor_api_v2.py）的改版重點------------------------------------------------1. 拿掉 rf / svm / ae / cnn_lstm 多模型架構，改成單一 XGBoost 模型。   這是目前 xgb_classifier_two_sensor_micro_final.py 訓練流程實際會   產出的唯一模型類型，v4.0 那套「每種模型各自載入一份」的設計目前   用不到，先簡化掉。如果之後真的要多模型並存，要再另外設計。2. 特徵工程整個換成新版 runtime pipeline   （two_sensor_feature_engineering_micro_30ml_final.py +    runtime_inference.py），包含：     - band_config_step2.json（leak_focused/resonance/offband 頻帶）     - feature_config_micro.json（window/hop/cusum 等參數 + 模型要用的       selected_feature_names）     - site_baseline.json（現場正常 baseline，正式版必填）   不再使用 v4.0 那個舊模組 two_sensor_feature_engineering 裡的   CORE_BANDS / AUX_BANDS 寫死常數。3. 告警判斷從 v4.0「單批次視窗投票（leak_ratio vs 兩個門檻）」，   換成新版 apply_alarm_method_by_record_runtime（連續窗觸發）   + apply_postprocessing（事件持續時間 + offband veto）的判斷邏輯，   跟你離線驗證過的 run_runtime_pipeline 是同一套函式、同一套規則。4. 拿掉洩漏量（leak_quantity_ml）與估計距離（distance_m）——   目前訓練流程只有分類器，沒有對應的迴歸模型，先整個移除，   避免前端顯示沒有根據的假數字。之後如果真的做了迴歸模型，   再把這塊加回來。5. DAQ_CAPTURE_SEC 設為 0.5 秒，搭配 StreamingRuntimeEngine 跨批次   累積 CUSUM 和 Temporal 特徵，不再需要拉長單次擷取時間。=============================================================================KNOWN LIMITATION（刻意接受的已知限制，時間許可時要回頭處理）============================================================- StreamingRuntimeEngine 已正確跨批次累積 CUSUM 和 Temporal 特徵。- _run_alarm_postprocess 的告警後處理每批次獨立計算，不跨批次累積告警狀態。  若洩漏事件剛好跨越兩批次邊界，有可能被切成兩段各自判斷。  下一階段考慮加入 StreamingAlarmEngine 解決。=============================================================================two_sensor_api_final.py — 氫能微洩漏即時偵測 API============================================================================= 整體架構】  前端（hydrogenhmi.html）      ↕ HTTP / WebSocket  FastAPI 後端（本檔）      ↕ import  runtime_inference.py（核心推論邏輯，跟離線評估共用同一套）      ↕ import  shared_feature_utils.py（特徵工程函式庫）=============================================================================【【啟動流程】  @app.on_event("startup") → load_runtime()      ├── load_runtime_configs()      讀五份設定檔（band / feature / postprocess /      │                               runtime_feature_schema / site_baseline）      ├── load_model_bundle()         載入 XGBoost 模型 + threshold      ├── 驗證 schema 與模型特徵一致      ├── deque(maxlen=fs×5)          初始化 Raw Signal Buffer      ├── StreamingRuntimeEngine()    初始化串流推論引擎      ├── alarm_buffer = deque()      初始化跨批次告警緩衝      └── 待機（等前端呼叫 /monitor/start 才啟動 DAQ）============================================================================= 【背景雙執行緒架構】   daq_worker（DAQ 執行緒）       ├── 每 0.5 秒從 NI DAQ 擷取 ai0 / ai1       ├── 更新 state.latest_waveform（波形預覽）       ├── 更新 state.signal_buffer_ai0/ai1（原始 Buffer）       └── 把新資料放入 inference_queue               ↓   inference_worker（推論執行緒）       ├── 從 inference_queue 取出新資料       ├── StreamingRuntimeEngine.process_chunk()       │     ├── StreamingWindowAssembler → 增量切窗       │     ├── DC removal + diff       │     ├── extract_required_window_features → Raw 特徵       │     ├── build_offband_summary_features → Summary       │     ├── _apply_fixed_baseline → rel_ / z_       │     ├── _update_cusum_features → CUSUM（跨批次累積）       │     ├── _update_temporal_features → delta / rolling       │     └── run_model_inference → leak_score / pred       │           ↓ df_predictions       └── _run_alarm_postprocess()             ├── apply_alarm_method_by_record() → Two-stage / consecutive / Veto             ├── apply_postprocessing() → min_leak_duration / event_state             └── summarize_event_state() → normal / disturbance_suspect / leak               ↓           更新 state.latest_inference_result============================================================================= 【三種 API 推論入口】   A. GET /realtime/waveform       └── 回傳最新波形（不等推論）   B. POST /realtime       └── 回傳最新波形 + 最新推論結果（合併）           暖機期間回傳 buffer_ready=False   C. POST /predict/tdms       └── 上傳 TDMS → build_runtime_feature_table()           → run_model_inference()           → _run_alarm_postprocess()（跟背景推論共用同一套）           → _build_resp()============================================================================= 【_run_alarm_postprocess 告警後處理流程】 （/realtime 背景推論 和 /predict/tdms 共用）   apply_alarm_method_by_record()    Two-stage / consecutive / Veto 規則       ↓   apply_postprocessing()            min_leak_duration / event_state       ↓   summarize_event_state()           → normal / disturbance_suspect / leak============================================================================= 【run_inference_pipeline 流程】（/predict/tdms 使用）   df_features       ↓ run_model_inference()   df_pred（含 leak_score）       ↓ _run_alarm_postprocess()   result dict（含 leak_status / score / confidence）=============================================================================【輔助端點】  GET  /models    列出可用模型  GET  /cfg       回傳目前 runtime 設定  GET  /status    系統狀態（ready / demo）  POST /clear     清除歷史紀錄  GET  /history   取得最近 N 筆結果=============================================================================【與 runtime_inference.py 的對應關係】API                                 Runtime──────────────────────────────────────────────────────signal_buffer（deque 5秒）          一次讀完整 TDMSStreamingRuntimeEngine              build_runtime_feature_table()_run_alarm_postprocess()            run_model_inference() + apply_postprocessing()buffer_ready 暖機檢查               無（離線不需要）DetectResponse JSON                 CSV / 分析結果=============================================================================RAW_BUFFER_SEC= raw signal 留在記憶體內多久= 由特徵工程的窗口、overlap、必要 lookback 決定CUSUM / rolling state= 另行保存的累積狀態= 不應因 raw buffer 滑動而歸零TRANSITION_CONFIRM_SEC= 偵測到疑似洩漏後，要持續多久才確認為穩定洩漏= 可參考物理穩態分析，但目前 3.20 秒樣本不足① 啟動與設定(line 235–516)AppState(303)— 全域狀態容器(所有背景執行緒共享的資料,你加的 alarm_buffer、stream_lag_sec 都在這)DetectResponse(368)— 回傳給前端的資料格式(你加的三個欄位在這)load_runtime(409)— 啟動時載入模型、設定、建 streaming engine_mount_static(503)— 掛前端 HTML② 特徵與推論核心(line 517–719)extract_features_live(520)— 即時特徵(這是舊的?要確認,因為 streaming engine 也算特徵)run_inference_pipeline(584)— 推論 + 告警的入口_run_alarm_postprocess(608)— 算 leak_status 的地方(你今天的核心,alarm_buffer 餵給它)_demo(703)— 假資料模式③ 波形預覽 + 組回應(line 721–845)_build_resp(797)— 把結果組成 DetectResponse(你今天加欄位改的地方)_get_signal_preview 那些 — 給前端畫波形用④ 背景執行緒(line 846–1198)← 你今天改最多的區_run_inference_on_buffer(850)— 舊的 buffer 推論(可能已不用?)daq_worker(953)— 讀 DAQ(你加的重連 reset 在這)inference_worker(1050)— 即時推論主迴圈(你加的 alarm_buffer、lag 計算、reset 在這)start_background_workers(1147)— 啟動兩個 worker⑤ API 端點(line 1199 之後)/models(1213)、/detect(1251)、/realtime(1266)— 前端 poll 這個、/predict/tdms、/status、/clear 那些"""import osimport jsonimport timeimport warningsimport tempfileimport tracebackimport asynciofrom pathlib import Pathfrom datetime import datetimefrom typing import Optional, Listimport numpy as npimport pandas as pdfrom scipy.signal import butter, filtfiltfrom collections import dequeimport queueimport threadingfrom fastapi.responses import HTMLResponsewarnings.filterwarnings("ignore")from fastapi import FastAPI, HTTPException, UploadFile, File, Form, WebSocket, WebSocketDisconnectfrom fastapi.middleware.cors import CORSMiddlewarefrom fastapi.staticfiles import StaticFilesfrom fastapi.responses import FileResponsefrom pydantic import BaseModel# ── 新版特徵工程（低階、可直接吃記憶體陣列的函式） ──from shared_feature_utils import (    sliding_window_records,    extract_window_features_core_bands,    compute_diff_signal,      remove_dc,    # 離線 TDMS 分析完成後，另外取出 ai0、ai1 提供前端顯示波形。    load_one_tdms_record,)# ── 新版 runtime pipeline（跟 run_runtime_pipeline 共用同一套函式） ──from runtime_inference import (    load_runtime_configs,    load_model_bundle,    resolve_runtime_band_groups,    run_model_inference,    apply_postprocessing,    summarize_event_state,    build_runtime_feature_table,    build_runtime_file_specs,    build_runtime_features_from_base_table,)from alarm_rule_utils import (    apply_alarm_method_by_record,)from runtime_streaming import (    StreamingRuntimeEngine,)# ============================================================# 設定路徑（依現場實際擺放位置調整）# ============================================================BASE_DIR = os.path.dirname(os.path.abspath(__file__))RESULT_DIR = os.path.join(BASE_DIR, "test_result")MODEL_ID = "xgb_20260923_164944"MODEL_DIR = os.path.join(RESULT_DIR, "saved_models_transition_disturbance_final", "xgb", MODEL_ID)BAND_CONFIG_PATH           = os.path.join(RESULT_DIR, "band_config_step2.json")FEATURE_CONFIG_PATH        = os.path.join(RESULT_DIR, "feature_config_micro.json")SITE_BASELINE_PATH         = os.path.join(RESULT_DIR, "site_baseline.json")POSTPROCESS_CONFIG_PATH    = os.path.join(MODEL_DIR, "postprocess_config.json")RUNTIME_FEATURE_SCHEMA_PATH = os.path.join(MODEL_DIR, "runtime_feature_schema.json")MODEL_METADATA_JSON        = os.path.join(MODEL_DIR, "metadata.json")FEATURE_EXTRACTION_CONFIG_PATH = os.path.join(RESULT_DIR, "feature_extraction_config.json")    # 正式底層特徵萃取設定檔。MODEL_DISPLAY_NAME = "XGBoost（雙感測器）"# ============================================================# ★ DAQ 設定區(指定 DAQ 的 AI0 類比輸入通道)# ============================================================DAQ_CHANNEL_AI0 = "cDAQ9181-210F82CMod1/ai0"   # far sensorDAQ_CHANNEL_AI1 = "cDAQ9181-210F82CMod1/ai1"   # near sensor# Windows 接 NI-DAQ 時設為 True。# Mac／沒有接 NI-DAQ 時設為 False。ENABLE_HARDWARE_DAQ = False# 每次實際從 DAQ 擷取 1.0 秒原始資料。# 這 1 秒資料會被切成多個 window 後進入模型推論。DAQ_CAPTURE_SEC = 1.0     # 人工巡檢模式下，每 5 秒執行一次 DAQ 擷取與推論。# 現場測試結果：3 秒會造成 inference_queue 滿載，5 秒可穩定運行。# 注意：此設定不是全時連續監測，而是週期式取樣推論。DAQ_LOOP_INTERVAL_SEC = 5.0   # 後端最多保存幾筆歷史紀錄（匯出 CSV 能拿到的上限）# 每 5 秒一筆，1000 筆約 83 分鐘HISTORY_MAX_RECORDS = 1000# 最近原始訊號的保留長度，用於顯示與事件留存。# 雖然每 0.5 秒抓一次新資料，但如果網頁只顯示 0.5 秒的波形，畫面會閃爍得太快、人類根本看不懂。所以記憶體會像傳送帶一樣，永遠保留最近 5 秒鐘的完整波形軌跡。RAW_BUFFER_SEC = 5.0# 系統啟動後，累積狀態多久才對外輸出正式告警。STARTUP_WARMUP_SEC = 5.0# 跨批告警滑動緩衝長度（秒），是防止警報「斷斷續續」的綜合評判時間，這個 10.0 秒的緩衝區代表系統會查看最近 10 秒鐘內的「整體上下文歷史」。ALARM_CONTEXT_SEC = 10.0       # 可依據最終後處理規則做最終調整DAQ_VOLT_MIN = -10.0      # 設定 DAQ 電壓輸入範圍 -10 V ~ +10 VDAQ_VOLT_MAX = 10.0# ============================================================# 顯示用濾波設定（跟模型判斷無關，純粹讓波形圖好看）# ============================================================DISPLAY_FILTER_LOW = 5_000DISPLAY_FILTER_HIGH = 170_000DISPLAY_PREVIEW_SEC = DAQ_CAPTURE_SEC     # 前端波形顯示整批擷取的長度# ============================================================# Runtime 終端機輸出控制# True：開發測試用，顯示每批 DAQ 點數、Window 數及計算時間。# False：正式展示用，只保留啟動資訊、警告與錯誤。# ============================================================RUNTIME_VERBOSE = False# Queue 持續滿載時，每隔幾秒才顯示一次警告。OVERRUN_LOG_INTERVAL_SEC = 10.0# ============================================================# FastAPI App(建立一個 FastAPI application - 整個 API 伺服器的主體)# ============================================================app = FastAPI(    title="H₂ 微洩漏智慧檢測 API",    description="氫能洩漏即時診斷後端 v5.0（雙感測器，新版 runtime pipeline）",    version="5.0.0",)# 加入 CORS middleware (為了安全起見，瀏覽器預設不允許網頁向「不同來源（Origin）」的伺服器發送請求並讀取資料)app.add_middleware(    CORSMiddleware,    allow_origins=["*"], allow_methods=["*"], allow_headers=["*"],    # allow_origins=["*"],代表：接受所有來源的前端。 -> 允許所有 HTTP methods 和 headers)# ============================================================# FastAPI 直接回傳 HTML# ============================================================@app.get("/", response_class=HTMLResponse)async def index():    html = Path(BASE_DIR, "hydrogenhmi.html",).read_text(encoding="utf-8")    return HTMLResponse(content=html)# ============================================================# 全局狀態# ============================================================# 建立一個類別，用來存放：整個 FastAPI 執行期間都要共用的狀態。# 當使用者在前端網頁點擊「啟動監控」或「切換分頁」時，後端需要有一個地方安全地記住當前系統運作的所有現狀class AppState:    def __init__(self):        # -- 1.系統初始化與狀態組        self.runtime_cfg = None       # 存五份 runtime 設定檔整理後的設定        self.model_bundle = None      # 存模型相關資訊        self.ready = False            # 模型與 runtime 是否準備完成:模型載入好了沒、參數讀取對了沒        # -- 2.即時數據監控與傳送帶（記憶體緩衝區）:負責存放從硬體（DAQ 卡）源源不絕抓下來的最新訊號        # 是否正在進行即時感測器監控,記錄當前是不是「正在自動監控中」。對應到你前端網頁點擊了啟動，這裡就會變成 True        self.monitoring_active = False        # 最近5秒原始雙通道資料(存放最近 5 秒鐘遠端與近端感測器原始電壓訊號)        self.signal_buffer_ai0 = None        self.signal_buffer_ai1 = None        # 最新取得的波形預覽。        self.latest_waveform = None                # 每取得一批新 DAQ 波形便加 1，前端利用它避免重複加入同一批波形。        self.waveform_seq = 0                # -- 3.多執行緒安全鎖        # 執行緒共用資料鎖，當 AI 正在讀取這 5 秒的波形資料時，鎖住數據，不讓 DAQ 卡在這個瞬間塞新資料進來吵架；等 AI 讀完放開鎖，DAQ 才能更新資料。        self.data_lock = threading.Lock()                # 避免同時重複啟動或停止背景執行緒，防止使用者在網頁上「連續瘋狂點擊」啟動/停止按鈕。確保前一次啟動命令還沒跑完前，下一次點擊會被擋住。        self.worker_lock = threading.Lock()        # -- 4.串流推論生產線（最核心的排隊機制）        # 每一批 DAQ 新資料都必須依序交給串流引擎，Queue 與 Event 不同，不會把多次通知合併成一次。        # 一個排隊箱，最多只允許放 2 批資料。DAQ 抓完 0.5 秒的資料，就丟進箱子排隊；AI 推論引擎再從箱子裡拿出來分析。        self.inference_queue = queue.Queue(maxsize=4)                # 真正執行新增 Window、CUSUM、Temporal 與模型的引擎。        self.streaming_engine = None                # Queue 已滿代表推論速度跟不上資料擷取速度。        # 這種情況不可默默丟資料，否則時間狀態會不連續。        self.streaming_overrun = False                # -- 5.歷史紀錄與告警綜合判定        # 最新完成的模型結果。        self.latest_inference_result = None        self.history = []             # 存歷史檢測結果        self.last_result = None                # 跨批告警滑動緩衝（每列 = 一個 window 預測）        # 一個滑動緩衝佇列，用來記錄最近幾次推論的連續結果，用來綜合評估，決定網頁要不要正式亮起紅色的「H₂ 洩漏告警」        self.alarm_buffer = deque()         # 關閉背景執行緒。        self.stop_event = threading.Event()        self.daq_thread = None        self.inference_thread = None                # 重連後請求重置串流引擎        self.need_stream_reset = False           # 累積落後秒數        self.stream_lag_sec = 0.0             self.daq_error = None                self.last_overrun_log_time = 0.0state = AppState()# ============================================================# Pydantic 資料格式:定義 /detect API 接收到的 JSON 格式# ============================================================class DetectRequest(BaseModel):    # 請求輸入：DetectRequest（前端給後端什麼）    """    雙感測器輸入格式。    ai0 = far sensor（背景參考）    ai1 = near sensor（靠近洩漏點）    兩者都為 None → Demo 模式。    """    ai0: Optional[list] = None    ai1: Optional[list] = None# API 最後要回傳給前端什麼, 回傳結果：DetectResponse（後端給前端什麼）class DetectResponse(BaseModel):        # -- 1.AI 推論與狀態（前端拿來切換燈號、顏色）    is_leak: bool               # 是否為洩漏？    leak_status: str            # "normal" 正常狀態(綠色) / "disturbance_suspect" 疑似干擾(橘色) / "leak" 洩漏狀態(紅色)    label: str    confidence: float           # 這次擷取中 leak-like windows 所佔的比例 × 100，這批 0.5 秒的資料切成多個 window 後，有多少比例的 window 被判定為洩漏    score: float                # 這次擷取裡最高的 leak_score    threshold: float            # 模型使用的 threshold    calc_time_sec: float        # 這次運算花多少秒    latency_sec: Optional[float] = None       # 計算端到端延遲    timestamp: str              # 檢測時間    model_display_name: str     # 前端顯示的模型名稱    is_demo: bool               # 是不是 Demo 模式    # 資料來源    source: str = "live"        # 即時資料會自動使用Live    source_name: Optional[str] = None    n_total_windows: Optional[int] = None           # 總共有幾個 window    n_leak_windows: Optional[int] = None            # 其中幾個 leak    n_disturbance_windows: Optional[int] = None     # 其中幾個 disturbance    # -- 2.波形圖表數據    # 前端顯示的原始波形    signal_preview_ai0: Optional[list] = None    signal_preview_ai1: Optional[list] = None    signal_preview_ai0_filtered: Optional[list] = None    # 顯示用濾波後波形(這些 filtered signal 不會拿去做模型判斷)    signal_preview_ai1_filtered: Optional[list] = None    # 顯示用濾波後波形(這些 filtered signal 不會拿去做模型判斷)    signal_preview_fs: Optional[float] = None    signal_preview_duration_sec: Optional[float] = None    # 用原始訊號算的統計值（不是用降採樣後的預覽算）    signal_rms_ai1: Optional[float] = None    signal_peak_ai1: Optional[float] = None        # 即時波形批次資訊。    waveform_seq: Optional[int] = None    waveform_timestamp: Optional[str] = None    window_probas: Optional[list] = None        # -- 3.系統健康度與即時性（後端自我監控）    # buffer 欄位    buffer_ready: bool = True              # 告訴網頁現在記憶體累積了幾秒的資料，目標是達到 RAW_BUFFER_SEC（也就是你之前設定的 5.0 秒）    buffer_sec_current: float = 0.0    buffer_sec_target: float = RAW_BUFFER_SEC        # 即時性指標    stream_lag_sec: float = 0.0           # 累積落後秒數    stream_realtime_ok: bool = True       # 這批算得夠不夠即時    streaming_overrun: bool = False       # queue 是否曾滿（硬性掉資料）# ============================================================# 啟動流程：載入五份正式設定檔 + 模型（一次載入，全程共用），初始化 5 秒訊號 buffer（跨輪累積用）# 當啟動後端程式時，@app.on_event("startup") 會命令系統在對外開放網頁前，先把所有 AI 模型、硬體設定檔通通載入並檢查完畢。# ============================================================@app.on_event("startup")def load_runtime():     # FastAPI 啟動時，自動執行下面的 load_runtime()    print("\n" + "=" * 60)    print("H₂ 微洩漏智慧檢測系統（雙感測器）— 載入 runtime pipeline v5.0")    print("=" * 60)    # 將 5 份設定檔路徑建立成 dictionary    required_paths = {        "band_config_path": BAND_CONFIG_PATH,                                  # 正式頻帶設定：leak-focused / resonance / offband        "feature_config_path": FEATURE_CONFIG_PATH,                            # 模型特徵設定：selected features / CUSUM / threshold 等        "postprocess_config_path": POSTPROCESS_CONFIG_PATH,                    # 正式後處理規則：consecutive / min duration / veto 等        "runtime_feature_schema_path": RUNTIME_FEATURE_SCHEMA_PATH,            # 部署欄位契約：模型欄位與規則欄位清單        "site_baseline_path": SITE_BASELINE_PATH,                              # 固定正常 baseline：rel/z 計算用 mean/std        "model_metadata_json": MODEL_METADATA_JSON,                            # 模型 metadata：模型 ID、特徵順序、threshold 等        "feature_extraction_config_path": FEATURE_EXTRACTION_CONFIG_PATH,      # 底層特徵萃取設定：window/hop/fs/nperseg/max_points    }    # 把所有不存在的檔案找出來    missing = [k for k, p in required_paths.items() if not os.path.exists(p)]    if missing:   # 如果有任何檔案缺失,印出缺哪些,進入 Demo 模式，然後結束 startup        print(f"⚠️  找不到以下設定檔，進入 Demo 模式: {missing}")        _mount_static()        return    try:        # 正式載入 runtime config        # 讀五份設定檔（band / feature / postprocess / runtime_feature_schema / site_baseline）, 最後放進：state.runtime_cfg        state.runtime_cfg = load_runtime_configs(            band_config_path=BAND_CONFIG_PATH,                                 # 正式頻帶設定，決定 runtime 要計算哪些 leak-focused / resonance / offband 頻帶。            feature_extraction_config_path=FEATURE_EXTRACTION_CONFIG_PATH,     # 底層特徵萃取設定，決定 window_sec、hop_sec、fs、nperseg、max_points 等。這個要和 feature_config_micro.json / site_baseline.json 的 hash 對得上。            feature_config_path=FEATURE_CONFIG_PATH,                           # 模型特徵設定，記錄 selected_feature_names、CUSUM 參數、score_col 等。            postprocess_config_path=POSTPROCESS_CONFIG_PATH,                   # 正式後處理規則設定，記錄目前定案的告警規則。            runtime_feature_schema_path=RUNTIME_FEATURE_SCHEMA_PATH,           # 正式部署欄位 schema，定義模型需要哪些欄位、規則需要哪些欄位。            site_baseline_path=SITE_BASELINE_PATH,                             # 固定正常 baseline，runtime 用它建立 rel_* 和 z_* 特徵        )                # 載入 XGBoost 模型 + threshold        state.model_bundle = load_model_bundle(MODEL_METADATA_JSON)                # runtime schema 與模型 metadata 必須指向同一組特徵。        schema_features = list(state.runtime_cfg["model_feature_names"])        model_features = list(state.model_bundle["feature_names"])                # 檢查「後端準備要計算的特徵（Schema）」跟「AI 模型當初訓練時認得的特徵（Metadata）」是否相同、順序有沒有錯        if schema_features != model_features:            raise ValueError(                "runtime_feature_schema.json 與 metadata.json 的模型特徵不一致。"            )                    state.ready = True    # 代表：現在模型和 runtime 已經準備好了。                        # 初始化 5 秒訊號 buffer（跨輪累積用）        # deque（雙端佇列）並設定了最大長度（fs 頻率 × RAW_BUFFER_SEC 5秒）。是一個會自動吐掉舊資料的傳送帶        fs = int(state.runtime_cfg["fs"])     # 正式 runtime 的 sampling frequency        state.signal_buffer_ai0 = deque(maxlen=int(fs * RAW_BUFFER_SEC))     # AI0 最多保留 500 萬個 sample        state.signal_buffer_ai1 = deque(maxlen=int(fs * RAW_BUFFER_SEC))     # AI1 最多保留 500 萬個 sample        # 啟動引擎：最後把這些設定與緩衝區塞進 StreamingRuntimeEngine（串流即時引擎），正式把發動機組裝好        state.streaming_engine = StreamingRuntimeEngine(runtime_cfg=state.runtime_cfg, model_bundle=state.model_bundle,)        rc = state.runtime_cfg        print(f"✅ runtime pipeline 載入成功")        print(f"   window_sec={rc['window_sec']}  hop_sec={rc['hop_sec']}  fs={rc['fs']}")        print(f"   alarm_method={rc['alarm_method']}  consecutive={rc['consecutive']}"              f"   window_threshold={rc['window_threshold']}")        print(f"   min_leak_duration_sec={rc['min_leak_duration_sec']}  use_veto={rc['use_veto']}")        print(f"   模型特徵數: {len(state.model_bundle['feature_names'])}")        print("    model_id =", MODEL_ID)        print("    model features =", state.model_bundle["feature_names"],)        print("    runtime schema =", RUNTIME_FEATURE_SCHEMA_PATH,)        model_threshold = float(state.model_bundle["window_threshold"])        rule_threshold = float(rc["window_threshold"])                # 檢查「AI 模型內建的判定門檻」跟「後處理工廠告警規則的門檻」是否相同        if abs(model_threshold - rule_threshold) > 1e-12:            print("⚠️  模型 threshold 與 postprocess rule 的 window_threshold 不一致")            print(f"   model threshold = {model_threshold}")            print(f"   rule threshold  = {rule_threshold}")    except Exception as e:        traceback.print_exc()        print(f"❌ runtime pipeline 載入失敗，進入 Demo 模式: {e}")        state.ready = False    _mount_static()        # API 啟動時只載入模型與正式設定。    # 等使用者按下「自動監控」後，才真正啟動 DAQ 與串流推論。    if state.ready:        print("✅ 模型與 Runtime 已就緒，目前處於待機模式")# ============================================================# 將前端網頁檔案與後端 FastAPI 伺服器「合而為一」:把前端 HTML 檔案掛載到 FastAPI 的靜態檔案服務上# ============================================================def _mount_static():    # 找到 hydrogenhmi.html 的完整路徑，BASE_DIR 是 two_sensor_api_final2.py 所在的資料夾。    html_path = os.path.join(BASE_DIR, "hydrogenhmi.html")    if os.path.exists(html_path):        try:            # 如果 HTML 檔案存在，就把 BASE_DIR 整個資料夾掛載成靜態檔案伺服器，這樣瀏覽器可以直接透過 http://localhost:8000/hydrogenhmi.html 存取前端頁面            app.mount("/", StaticFiles(directory=BASE_DIR, html=True), name="static")            print(f"✅ 前端介面: http://localhost:8000/hydrogenhmi.html")        except RuntimeError:            pass    else:    # 如果 HTML 檔案不存在，提示用另一個方式開前端        print("ℹ️  前端：python -m http.server 5500")# ============================================================# 即時（記憶體陣列）特徵工程：把 DAQ 的兩個 numpy array → 模型需要的 feature DataFrame# ============================================================def extract_features_live(ai0: np.ndarray, ai1: np.ndarray, runtime_cfg: dict,                           record_id: str = "live_capture") -> pd.DataFrame:    """    這支函式是 runtime_inference.py 的 build_runtime_feature_table 的「即時版」——邏輯必須跟它保持一致，差別只在第一步：      - build_runtime_feature_table：從 TDMS 檔案路徑讀訊號    TDMS → 讀檔 → feature      - 這裡：直接吃 DAQ 即時擷取到、還在記憶體裡的 ai0/ai1 陣列   DAQ array → feature    後面 baseline / CUSUM / temporal / offband summary 這幾步，跟離線版本共用完全相同的函式，只是省去了寫檔/讀檔跟快取。    基礎頻帶特徵建立完成後，統一交由    build_runtime_features_from_base_table() 處理，    因此後段特徵工程會自動與離線 runtime 保持一致。    """    fs = runtime_cfg["fs"]                    # sampling frequency    window_sec = runtime_cfg["window_sec"]    # window 長度    hop_sec = runtime_cfg["hop_sec"]          # hop 長度    # 確保輸入變成 numpy array, 並且是float64    ai0 = np.asarray(ai0, dtype=np.float64)    ai1 = np.asarray(ai1, dtype=np.float64)        # 去直流成分 DC remove    ai0, ai1 = remove_dc(ai0, ai1)    # 建立 record    record = {        "filename": f"{record_id}.live",        "record_id": record_id,        "fs": fs,        "meta": {},        "signal": {"ai0": ai0, "ai1": ai1},        "label": -1,      # 因為現在是 inference：沒有真實答案，所以 label = -1。    }    # ── 第一步（即時版）： 建立 diff 通道 + 切窗 + 算基礎 band 特徵 ──    records = compute_diff_signal([record])    windows = sliding_window_records(records, fs=int(fs), window_sec=window_sec, hop_sec=hop_sec)    if not windows:        raise ValueError(            f"訊號太短，無法切出視窗。"            f"訊號長度={len(ai1)} 點，需要至少 {int(fs * window_sec)} 點"        )    # -- 特徵工程 --    # 讀進正式 band config，並轉成 RuntimeBandGroups    band_groups = resolve_runtime_band_groups(runtime_cfg["band_config"])        # 真正計算每個 window 的基礎特徵    feature_rows = extract_window_features_core_bands(        windows,        core_bands=band_groups.core_bands,      # core_bands把leak_focused_bands跟resonance_bands合併起來        aux_bands=band_groups.aux_bands,        # aux_bands直接對應offband_bands,原封不動搬過去        low_bands=band_groups.low_bands,        # low_bands固定給空清單        verbose=False,    )    # 把 feature rows 組成 DataFrame    df = pd.DataFrame(feature_rows).reset_index(drop=True)    df = df.sort_values(["record_id", "t_ref"]).reset_index(drop=True)    # 回傳將已切窗的基礎頻帶特徵表，轉成正式 runtime 特徵表    return build_runtime_features_from_base_table(df, runtime_cfg)# ============================================================# 核心推論：跑模型 + 告警規則 + 事件後處理 + 摘要# 跟 run_runtime_pipeline 用的是同一套函式，只是輸入來源不同# ============================================================def run_inference_pipeline(df_features: pd.DataFrame,                            runtime_cfg: dict,                            model_bundle: dict) -> dict:    # -- 嚴格的特徵全面總點檢（防爆安全閥） --    required_model_cols = runtime_cfg["model_feature_names"]        # 取得：模型真正需要哪些 feature。    # 檢查 feature 有沒有缺, 如果缺 feature 直接停止，不讓模型亂跑。    missing_model_cols = [c for c in required_model_cols if c not in df_features.columns]    if missing_model_cols:        raise ValueError(f"缺少模型需要的欄位: {missing_model_cols[:10]}")    # 模型預測    df_pred = run_model_inference(        df_features=df_features,        model_bundle=model_bundle,        score_col=runtime_cfg["score_col"],        pred_col=runtime_cfg["pred_col"],        threshold_override=(runtime_cfg["window_threshold"]),    )    return _run_alarm_postprocess(df_pred, runtime_cfg, model_bundle)# ============================================================# 告警後處理（從已有 leak_score 的 df_pred 開始）# inference_worker 和 run_inference_pipeline 共用# ============================================================def _run_alarm_postprocess(df_pred: pd.DataFrame,                            runtime_cfg: dict,                            model_bundle: dict) -> dict:    # 共用 alarm_rule_utils 使用 pred_proba 作為輸入欄位    df_rule_input = df_pred.copy()    df_rule_input["pred_proba"] = pd.to_numeric(df_rule_input[runtime_cfg["score_col"]], errors="coerce").fillna(0.0)    # 整理正式告警、two-stage 與 veto 規則    formal_rule_cfg = {        "method": runtime_cfg["alarm_method"],        "alarm_threshold": runtime_cfg["alarm_threshold"],        "smooth_window": runtime_cfg["smooth_window"],        "consecutive": runtime_cfg["consecutive"],        "n_hits": runtime_cfg["n_hits"],        "m_window": runtime_cfg["m_window"],        "high_threshold": runtime_cfg["high_threshold"],        "low_threshold": runtime_cfg["low_threshold"],                # 最短持續時間限制        "min_leak_duration_sec": runtime_cfg["min_leak_duration_sec"],                # 檢查 veto_column（通常是其他非主要頻帶的能量比值）,如果發現其他雜音頻帶的能量也一起同步暴增, 那大概率就是干擾‘        "use_veto": runtime_cfg["use_veto"],        "veto_column": runtime_cfg["veto_column"],        "veto_threshold": runtime_cfg["veto_threshold"],        "veto_rules": runtime_cfg["veto_rules"],                # 雙門檻機制 (Two-Stage)        "stage1": runtime_cfg["stage1"],      # 高門檻：一踩到立刻爆警        "stage2": runtime_cfg["stage2"],      # 低門檻：已經高於低門檻，就不立刻告警，而是要求它「連續維持一段時間」或「連續 N 個 window」才告警    }    # 套用與 disturbance／transition 驗證相同的正式規則    df_alarm = apply_alarm_method_by_record(        df_pred=df_rule_input,        cfg=formal_rule_cfg,        window_threshold=runtime_cfg["window_threshold"],    )    # 統一成 Runtime 後續使用的欄位名稱    df_alarm["alarm_detected"] = df_alarm["detected_rule"]    df_alarm["alarm_detected_raw"] = df_alarm["detected_rule_raw"]    df_alarm["alarm_score_smooth"] = df_alarm["smoothed_proba_rule"]    # alarm_rule_utils 已經處理：    # 1. two-stage    # 2. min_leak_duration_sec    # 3. veto_rules    # 進一步判斷：leak vs disturbance_suspect vs normal    # two-stage、最短持續時間與 veto 已由 apply_alarm_method_by_record() 處理。此處只轉換成事件狀態，不重複套規則。    df_post = apply_postprocessing(        df_pred=df_alarm,        score_col=runtime_cfg["score_col"],        pred_col="alarm_detected",        group_col="record_id",        time_col="t_ref",        window_sec=runtime_cfg["window_sec"],        min_consecutive_windows=1,      # 理由同 run_runtime_pipeline：alarm_detected 已由 consecutive 篩過一次        min_leak_duration_sec=0.0,        disturbance_ratio_col=runtime_cfg.get("disturbance_ratio_col", "offband_to_leak_focus_E_ratio"),        disturbance_ratio_threshold=None,    )    # Record summary(把很多 windows -> 一個 record)    df_summary = summarize_event_state(        df_post=df_post,        group_col="record_id",        state_col="event_state",        score_col=runtime_cfg["score_col"],    )    # 因為這次 live inference 是一個 record，所以取第一列    row = df_summary.iloc[0]    leak_status = row["final_state"]    n_total = int(row["n_total_windows"])    n_leak = int(row["n_leak_windows"])    n_dist = int(row["n_disturbance_windows"])    max_score = float(row["max_leak_score"]) if pd.notna(row["max_leak_score"]) else 0.0       # 取得整次資料最高的 leak score    confidence = 100.0 * (n_leak + n_dist) / n_total if n_total > 0 else 0.0                   # 這次資料有多少比例的 window 被認為是異常／leak-like    return {        "leak_status": leak_status,                               # 傳給前端亮燈（綠/橘/紅）        "is_leak": leak_status == "leak",                         # 告訴前端要不要拉響大警報        "score": max_score,                                       # 畫在前端儀表板的指針分數        "threshold": float(model_bundle["window_threshold"]),         "confidence": round(confidence, 1),                       # 顯示在前端的信心度百分比        "n_total_windows": n_total,          "n_leak_windows": n_leak,        "n_disturbance_windows": n_dist,        "window_probas": pd.to_numeric(                           # 傳給前端拿來畫歷史趨勢折線圖的數據            df_post[runtime_cfg["score_col"]], errors="coerce"        ).fillna(0.0).tolist(),    }# ============================================================# 波形處理工具（跟模型判斷無關，純顯示用）# ============================================================def _bandpass_preview_signal(signal, fs, lo, hi, order=4):    # 工廠現場的原始訊號（Raw Signal）通常極度髒亂，充斥著環境的低頻震動（像是地板晃動、馬達運轉）與高頻電子雜訊（白雜訊）。    # 帶通濾波器會根據你設定的最低頻率 lo 和最高頻率 hi，在波形上套一個過濾網，只允許這個頻段內的訊號通過，其餘雜音通通濾掉。    # 傳統的濾波器在過濾雜訊後，會導致訊號在時間軸上產生「相位延遲」（也就是波形會稍微往右平移錯位）。但在這裡使用了高級的 `filtfilt`（雙向濾波技術）。    # 它把訊號正著濾一次、再反著濾一次，**把雜訊濾乾淨的同時，還能確保波形時間點跟原始數據完全對齊，絕對不會移位**！        # 安全防線 1：如果傳進來的訊號根本是空的（None），直接結束回傳 None    if signal is None:        return None    # 將輸入的訊號轉換成標準的 NumPy 陣列，並強制指定為高精度的 float64 浮點數型態    sig = np.asarray(signal, dtype=np.float64)        # 安全防線 2：如果陣列裡面的元素數量為 0（空陣列），直接把空陣列丟回去    if sig.size == 0:        return sig    # 計算奈奎斯特頻率 (Nyquist Frequency)：取樣頻率的一半，這是數位訊號處理能分析的最高上限    nyq = fs / 2.0    lo_n = lo / nyq                  # 計算奈奎斯特頻率 (Nyquist Frequency)：取樣頻率的一半，這是數位訊號處理能分析的最高上限    hi_n = min(hi / nyq, 0.999)      # 將我們要過濾的最高頻率 (hi) 除以最高上限，並確保不能大於 1，最高只能到 0.999 (正規化最高頻率)        # 安全防線 3：如果最低頻率設定小於等於 0，或者最低頻率居然比最高頻率還要大（不合邏輯），直接放行回傳原訊號    if lo_n <= 0 or lo_n >= hi_n:        return sig        # 安全防線 4：根據濾波器的階數 (order) 計算所需的「最少資料點數」，通常濾波器需要一定長度的訊號才能開工    min_len = max(32, order * 12)        # 安全防線 5：如果實體訊號的點數太少，不夠濾波器塞牙縫，直接放棄濾波、回傳原始訊號    if sig.size < min_len:        return sig    try:        # 使用 scipy 套件的 butter 函式，建立一組巴特沃斯（Butterworth）帶通（band）濾波器的數學係數 (b, a)        b, a = butter(order, [lo_n, hi_n], btype="band")        # 執行雙向濾波（filtfilt）：正著濾一次、反著濾一次，可以完美消除訊號時間位移，並強轉成 float64 輸出        return filtfilt(b, a, sig).astype(np.float64)     except Exception as e:        print(f"  ⚠️ 顯示濾波失敗，改回原始訊號: {e}")        # 就算失敗也絕不崩潰，直接將完全沒處理過的原始訊號回傳，確保網頁圖表依然有畫面        return sig        # ============================================================# 波形可以覆蓋舊畫面，但送給 CUSUM 的 Window 不可任意丟棄，否則累積狀態會斷掉# ============================================================@app.get("/realtime/waveform")      # /realtime/waveform 路由（前端來拿最新圖表數據）def get_latest_waveform():    # 使用 state.data_lock 交通警察鎖，確保讀取波形時，DAQ 線程不會同時進來修改它    with state.data_lock:        waveform = state.latest_waveform     # 從全域狀態中把最新一輪取得的波形數據拷貝出來    # 如果目前還沒有任何波形（剛開機硬體還沒抓到資料）    if waveform is None:        return {            "ready": False,            "message": "尚未取得DAQ訊號",        }        # 如果有資料，回傳準備就緒，並用 ** 語法將 waveform 字典裡的所有波形數據拆開合併回傳    return {        "ready": True,        **waveform,    }# ============================================================# 原始波形瘦身工具# ============================================================def _get_signal_preview(signal, fs, n=2000):    # 原始波形降採樣（顯示用，不影響模型）    # 把訊號切成 n/2 段，每段保留最大值和最小值，這樣就算尖峰只有幾個點，也一定會出現在畫面上        # 安全防線：如果訊號根本不存在或是長度為 0，直接回傳 None 結束    if signal is None or len(signal) == 0:        return None    try:        # 強轉成 NumPy 的 float64 高精度浮點數陣列        signal = np.asarray(signal, dtype=np.float64)                # 計算畫圖預覽要截取的點數。DISPLAY_PREVIEW_SEC = 0.5，代表只拿前 0.5 秒的訊號        raw_n = min(len(signal), int(fs * DISPLAY_PREVIEW_SEC))         # 鋸斷訊號，只切出前 0.5 秒長度的局部數據陣列        sig = signal[:raw_n]                # 點數本來就不多，不用降採樣        if len(sig) <= n:            return sig.tolist()                # 切成 n_buckets 段，每段 bucket_len 點（尾巴不足一段的捨去）        n_buckets = max(1, n // 2)        bucket_len = len(sig) // n_buckets        buckets = sig[:bucket_len * n_buckets].reshape(n_buckets, bucket_len)        mins = buckets.min(axis=1)        maxs = buckets.max(axis=1)        # 依照最大、最小值在原始訊號中出現的先後順序排列，波形形狀才不會失真        min_first = buckets.argmin(axis=1) <= buckets.argmax(axis=1)        out = np.empty(n_buckets * 2, dtype=np.float64)        out[0::2] = np.where(min_first, mins, maxs)        out[1::2] = np.where(min_first, maxs, mins)        return out.tolist()    except Exception as e:        print(f"  ⚠️ 預覽波形處理失敗: {e}")        return np.asarray(signal, dtype=np.float64)[:n].tolist()# ============================================================# 用原始訊號算 RMS 和 Peak（顯示用）# 先去直流，避免直流偏移讓數值偏大# ============================================================def _signal_stats(signal):    if signal is None or len(signal) == 0:        return None, None    x = np.asarray(signal, dtype=np.float64)    x = x - np.mean(x)    rms = float(np.sqrt(np.mean(x ** 2)))    peak = float(np.max(np.abs(x)))    return rms, peak   # ============================================================# 濾波波形瘦身工具# ============================================================# 原始訊號 -> 通過 5 kHz ~ 170 kHz 的帶通濾波網 -> 變成平滑的 filtered preview 給網頁畫圖def _get_filtered_signal_preview(signal, fs, n=2000):    # 安全防線：如果訊號是空的，直接拒絕往後執行，回傳 None    if signal is None or len(signal) == 0:        return None    try:        # 強轉成 NumPy 的 float64 陣列        signal = np.asarray(signal, dtype=np.float64)        # 同樣只切出前 0.5 秒長度的訊號數據點數        raw_n = min(len(signal), int(fs * DISPLAY_PREVIEW_SEC))        # 呼叫我們上一題學過的巴特沃斯帶通濾波器 _bandpass_preview_signal，傳入低頻閥值 (DISPLAY_FILTER_LOW) 與高頻閥值 (DISPLAY_FILTER_HIGH)，把 5k~170kHz 以外的雜訊洗乾淨        sig = _bandpass_preview_signal(signal[:raw_n], fs=fs, lo=DISPLAY_FILTER_LOW, hi=DISPLAY_FILTER_HIGH)        # 計算降採樣步長，確保洗乾淨的訊號也只留下 n=2000 點        step = max(1, len(sig) // n)        # 進行等間隔抽樣，並將濾波完美美顏後的波形轉成 list 回傳給前端        return sig[::step].tolist()    except Exception as e:        print(f"  ⚠️ 濾波預覽處理失敗: {e}")        # 因為這只是附加的濾波美化功能，失敗了就回傳 None，前端頂多不顯示濾波圖表，但主程式絕不崩潰        return None# ============================================================# 數據包裝:把內部 result dictionary → FastAPI 的 DetectResponse# ============================================================def _build_resp(result: dict, ai0=None, ai1=None) -> DetectResponse:    # 檢查這一輪推論是不是從 Demo 模式產出的（預設為 False）    demo = result.get("is_demo", False)    # 取得 AI 算完的最终狀態字串（"normal" / "disturbance_suspect" / "leak"）    leak_status = result["leak_status"]    # 建立一個翻譯字典，把生硬的英文狀態對應成漂亮的繁體中文標籤    label_map = {"normal": "正常狀態", "disturbance_suspect": "疑似干擾", "leak": "洩漏狀態"}    # 安全取得當前的取樣頻率 (fs)。如果開機點檢失敗沒設定檔，就給一個預設的 1 MHz 高頻率    fs = float(state.runtime_cfg["fs"]) if state.runtime_cfg else 1_000_000.0    # 取得系統目標要存滿幾秒的訊號水庫（預設是 RAW_BUFFER_SEC = 5.0 秒）    buffer_sec_target=result.get("buffer_sec_target", RAW_BUFFER_SEC)    rms_ai1, peak_ai1 = _signal_stats(ai1)    # 正式建立 API response    return DetectResponse(        is_leak=result["is_leak"],           # 是否判定為洩漏（True/False）        leak_status=leak_status,        label=label_map.get(leak_status, "未知狀態"),        confidence=result["confidence"],     # 異常信心度百分比        score=result["score"],               # 這次檢測的最高洩漏分數        threshold=result["threshold"],       # 這次檢測的最高洩漏分數        calc_time_sec=result.get("calc_time_sec", 0.0),         # 這次運算花費的秒數（可用來觀察效能）        latency_sec=result.get("latency_sec"),                  # 這批資料進 queue 到結果完成的總延遲        timestamp=datetime.now().strftime("%Y-%m-%d %H:%M:%S"), # 精準記錄這批資料算完的「西元年月日 時:分:秒」時間戳                # 組合前端要顯示的模型名稱。如果是 Demo 模式，會在名字後面加上 " (Demo)"        model_display_name=MODEL_DISPLAY_NAME + (" (Demo)" if demo else ""),        is_demo=demo,          # 是否為 Demo 模式        n_total_windows=result.get("n_total_windows"),        # 這次計算的總視窗數        n_leak_windows=result.get("n_leak_windows"),          # 判定為洩漏的視窗數        n_disturbance_windows=result.get("n_disturbance_windows"),        # 判定為干擾的視窗數                # ── 呼叫降採樣與濾波器工具（優化網頁圖表效能） ──        # 如果有傳入實體訊號，就呼叫 _get_signal_preview 將其瘦身成 2000 點傳給前端，否則給 None        signal_preview_ai0=_get_signal_preview(ai0, fs) if ai0 is not None else None,        signal_preview_ai1=_get_signal_preview(ai1, fs) if ai1 is not None else None,        # 同理，將實體訊號送進濾波器洗乾淨後，再瘦身成 2000 點的「美顏版波形」給網頁畫圖        signal_preview_ai0_filtered=_get_filtered_signal_preview(ai0, fs) if ai0 is not None else None,        signal_preview_ai1_filtered=_get_filtered_signal_preview(ai1, fs) if ai1 is not None else None,        signal_preview_fs=fs,                                # 告訴網頁這張圖原始的取樣頻率        signal_preview_duration_sec=DISPLAY_PREVIEW_SEC,     # 告訴網頁這張圖顯示的是幾秒鐘的長度（0.5秒）        signal_rms_ai1=rms_ai1,        signal_peak_ai1=peak_ai1,                # 歷史分數切片：從結果中拿出所有視窗的預測機率歷史，利用 Python 的 [-200:] 語法，永遠只截取最新、最尾端的 200 筆資料        window_probas=(result.get("window_probas") or [])[-200:] or None,        buffer_ready=result.get("buffer_ready", True),              # 水庫累積好了沒        buffer_sec_current=result.get("buffer_sec_current", 0.0),   # 當前水庫累積到了幾秒        buffer_sec_target=buffer_sec_target,        # ── 系統即時性監控健康指標 ──        stream_lag_sec=result.get("stream_lag_sec", 0.0),           # 系統累積落後秒數        stream_realtime_ok=result.get("stream_realtime_ok", True),  # 這批算得夠不夠即時        streaming_overrun=result.get("streaming_overrun", False),   # 排隊箱（Queue）有沒有爆滿過    )def _save_hist(resp: DetectResponse):    # 保存最後一次結果，將剛剛包裝好的 DetectResponse 轉換成 Python 字典格式，並覆蓋存入全域狀態 state 的最新結果抽屜    state.last_result = resp.dict()    # 把這次結果加入歷史紀錄    state.history.append(resp.dict())    # 最多保存 200 筆，超過就刪掉最舊的一筆。    if len(state.history) > 200:        state.history.pop(0)    # 利用 pop(0) 強制把最前面（索引值為 0）、最舊的那一筆歷史紀錄扔掉        '''# ============================================================# 背景模型工作使用：# 對已經累積完成的Raw Buffer執行推論# ============================================================def _run_inference_on_buffer(    ai0_buffer,    ai1_buffer,):    """    對已經累積完成的雙通道Buffer執行推論。    注意：    本函式不負責將新資料加入Buffer，    避免同一批DAQ資料被重複加入。    """    if not state.ready:        raise RuntimeError(            "正式模型尚未就緒"        )    ai0_buffer = np.asarray(        ai0_buffer,        dtype=np.float64,    )    ai1_buffer = np.asarray(        ai1_buffer,        dtype=np.float64,    )    if len(ai0_buffer) != len(ai1_buffer):        raise ValueError(            "ai0與ai1的Buffer長度不一致："            f"ai0={len(ai0_buffer)}，"            f"ai1={len(ai1_buffer)}"        )    fs = int(state.runtime_cfg["fs"])    required_samples = int(        fs * RAW_BUFFER_SEC    )    if len(ai0_buffer) < required_samples:        raise ValueError(            "Buffer尚未累積完成："            f"目前={len(ai0_buffer) / fs:.2f}秒，"            f"需求={RAW_BUFFER_SEC:.2f}秒"        )    t0 = time.perf_counter()    # 直接對傳入的Buffer建立正式特徵。    # 不再呼叫extend()，避免資料重複加入。    df_features = extract_features_live(        ai0_buffer,        ai1_buffer,        state.runtime_cfg,    )    result = run_inference_pipeline(        df_features,        state.runtime_cfg,        state.model_bundle,    )    result["calc_time_sec"] = round(        time.perf_counter() - t0,        3,    )    result["is_demo"] = False    result["buffer_ready"] = True    result["buffer_sec_current"] = round(        len(ai0_buffer) / fs,        2,    )    result["buffer_sec_target"] = RAW_BUFFER_SEC    return result'''# ============================================================# DAQ 工具：雙通道同步擷取# ============================================================def _daq_read_two_channels(fs: float):    import nidaqmx    from nidaqmx.constants import AcquisitionType, READ_ALL_AVAILABLE    # 每個 channel 每輪就是 100 萬點(fs = 1,000,000 Hz, DAQ_CAPTURE_SEC = 1 sec)    n_samps = int(fs * DAQ_CAPTURE_SEC)        with nidaqmx.Task() as task:      # 建立一個 NI-DAQ task        # 加入 AI0        task.ai_channels.add_ai_voltage_chan(DAQ_CHANNEL_AI0, min_val=DAQ_VOLT_MIN, max_val=DAQ_VOLT_MAX)        # 加入 AI1        task.ai_channels.add_ai_voltage_chan(DAQ_CHANNEL_AI1, min_val=DAQ_VOLT_MIN, max_val=DAQ_VOLT_MAX)        # 設定硬體時脈與擷取模式        # FINITE不是無限連續擷取，而是：抓指定數量後結束，指定每個通道抓滿 n_samps（50萬點）就收工。        task.timing.cfg_samp_clk_timing(fs, sample_mode=AcquisitionType.FINITE, samps_per_chan=n_samps)           data_raw = task.read(READ_ALL_AVAILABLE)     # 把可取得的資料讀出來    # DAQ raw data 轉成 numpy array。    ai0 = np.array(data_raw[0], dtype=np.float64)    ai1 = np.array(data_raw[1], dtype=np.float64)    return ai0, ai1# ============================================================# DAQ 背景工作# ============================================================def daq_worker():    """    唯一可以操作NI-DAQ的背景執行緒。    每 5 秒啟動一輪，每輪取得 1 秒雙通道訊號後：    1. 更新最新波形。    2. 加入Raw Signal Buffer。    3. 通知模型執行緒有新資料。    """    fs = float(state.runtime_cfg["fs"])      # 從開機載入的設定中取得取樣頻率（例如 1,000,000 Hz）    n_samps = int(fs * DAQ_CAPTURE_SEC)      # 計算這 0.5 秒內應該要拿到的標準點數（1,000,000 * 0.5 = 50 萬點）    # 狀態旗標：用來記錄硬體「上一輪是不是處於斷線狀態」，初始化為 False    was_disconnected = False        # 只要網頁或系統沒有發出停止訊號（stop_event 未被設定），這個背景輪詢就會永久卡住、無限循環執行    while not state.stop_event.is_set():        loop_started_at = time.perf_counter()        try:            # 核心步驟 1：向實體硬體抓資料, 呼叫上一題學到的驅動程式，拿回雙通道 50 萬點陣列            ai0, ai1 = _daq_read_two_channels(fs,)            # 安全驗證：嚴格檢查硬體吐出來的點數是不是「剛剛好等於 50 萬點」，如果點數不對代表硬體出包            _validate_signal(ai0, "ai0", n_samps,)            _validate_signal(ai1, "ai1", n_samps,)                        # 斷線後第一次成功讀取 → 時間軸已中斷            if was_disconnected:                state.need_stream_reset = True          # 時間軸中斷了，交給 inference_worker 重置引擎                state.stream_lag_sec = 0.0              # 延遲秒數歸零                                # 拿鎖保護，清除 5 秒大水庫與排隊箱，因為裡面的殘留訊號已經和現在的新訊號不連續了，必須丟棄                with state.data_lock:                    if state.signal_buffer_ai0 is not None:                        state.signal_buffer_ai0.clear()      # 清空 ai0 水庫                        state.signal_buffer_ai1.clear()      # 清空 ai1 水庫                    # 用一個迴圈，把排隊箱（Queue）裡面殘留的、斷線前的舊資料強制全部倒掉                    while not state.inference_queue.empty():                        try:                            state.inference_queue.get_nowait()                            state.inference_queue.task_done()                        except queue.Empty:                            break                # 重連清洗完畢，將斷線標記恢復為 False                was_disconnected = False                print("🔄 DAQ 重連，串流引擎將重置")            # 顯示用：去DC，但不做頻率濾波。            # 把這 50 萬點扣掉平均值（去直流），然後呼叫 _get_signal_preview 瘦身成 2000 點給網頁畫原始波形            preview_ai0 = _get_signal_preview(ai0 - np.mean(ai0),fs,)            preview_ai1 = _get_signal_preview(ai1 - np.mean(ai1), fs,)            rms_ai1, peak_ai1 = _signal_stats(ai1)            # 拿交通警察鎖，開始更新全域狀態資料，防範 AI 執行緒同時進來搶資料            with state.data_lock:                # 更新最近的波形，每次成功取得一批新訊號，波形編號加 1。                state.waveform_seq += 1                                # 塞入最新預覽包（此處只塞未濾波的 2000 點，濾波美顏版交給上層 API 動態計算，降低背景線程負擔）                state.latest_waveform = {                    "signal_preview_ai0": (preview_ai0),                    "signal_preview_ai1": (preview_ai1),                    "signal_preview_ai0_filtered": None,                    "signal_preview_ai1_filtered": None,                    "signal_preview_fs": fs,                    "signal_preview_duration_sec": (DISPLAY_PREVIEW_SEC),                    "signal_rms_ai1": rms_ai1,                    "signal_peak_ai1": peak_ai1,                    # 讓前端知道這是不是新的波形批次。                    "waveform_seq": state.waveform_seq,                    # 波形取得時間，與模型完成時間分開。                    "waveform_timestamp": (datetime.now().isoformat(timespec="milliseconds")                    ),                }                # Raw Buffer持續更新( 5 秒滑動大水庫持續塞入最新進來的這 50 萬點原始數據（extend 會自動擠掉 5 秒前最舊的 50 萬點）)。                state.signal_buffer_ai0.extend(ai0.tolist())                state.signal_buffer_ai1.extend(ai1.tolist())            # 將這批完整的新資料交給串流推論執行緒。            # 這裡傳入原始資料，不是前端 downsample 後的波形(未瘦身的 50 萬點原始數據)。            chunk = {                "ai0": np.asarray(ai0, dtype=np.float64,),                "ai1": np.asarray(ai1, dtype=np.float64,),                "captured_at": time.time(),            }                        state.streaming_overrun = False      # 每一輪成功讀到資料時，先歸零            try:                # 正常情況：把最新 DAQ chunk 放進推論 queue。                state.inference_queue.put(chunk, timeout=0.2)                        except queue.Full:                # 人工巡檢模式：                # 如果推論速度暫時跟不上，不要直接讓系統進入錯誤狀態。                # 先丟掉 queue 裡前半段較舊的 chunk，再把最新 chunk 放進去。                drop_count = max(1, state.inference_queue.qsize() // 2)                            for _ in range(drop_count):                    try:                        state.inference_queue.get_nowait()                        state.inference_queue.task_done()                    except queue.Empty:                        break                                    now = time.time()                if now - getattr(state, "last_overrun_log_time", 0.0) >= 5.0:                    print(                        f"⚠️ Queue 滿，已丟掉 {drop_count} 批舊資料，改放最新資料｜"                        f"qsize={state.inference_queue.qsize()}"                    )                    state.last_overrun_log_time = now                            try:                    state.inference_queue.put_nowait(chunk)                                # 這裡代表有成功把最新資料放進去，所以不要視為硬體錯誤。                    state.streaming_overrun = True                    state.daq_error = None                            except queue.Full:                    # 如果丟掉一半後還是滿，代表推論端真的卡住。                    # 這時才保留 Queue 滿的錯誤狀態。                    state.streaming_overrun = True                    state.daq_error = "串流推論速度跟不上 DAQ，inference_queue已滿"                                        print("⚠️ Queue 曾滿載，本批已套用丟舊保新策略，時間連續性降低")            else:                # 只有真的沒有塞爆、成功放進 queue，才代表這一輪沒有 DAQ/推論錯誤                state.daq_error = None                        if RUNTIME_VERBOSE:     # 如果有開啟詳細日誌開關，就在終端機印出成功抓到訊號的日誌                print(                    f"✅ DAQ背景擷取："                    f"ai0={len(ai0)}，"                    f"ai1={len(ai1)}"                )            elapsed = time.perf_counter() - loop_started_at            sleep_sec = max(0.0, DAQ_LOOP_INTERVAL_SEC - elapsed)                    if sleep_sec > 0:                time.sleep(sleep_sec)        except Exception as exc:            # 如果 _daq_read_two_channels 崩潰（例如擷取卡被拔掉、沒通電、驅動噴錯），把錯誤訊息寫進全局狀態，讓網頁端能直接看到紅字硬體報錯            state.daq_error = str(exc)            was_disconnected = True     # 標記斷線            print(f"❌ DAQ背景擷取失敗：{exc}")            # 硬體故障時，不允許盲目地瘋狂轉圈嘗試、這會讓 CPU 瞬間飆到 100% 導致整台電腦卡死。            # 這裡故意強制讓迴圈「躺平睡覺 1.0 秒」            time.sleep(1.0)                        # ============================================================# 模型背景工作# ============================================================def inference_worker():    """    依序處理每一批新增 DAQ 資料。    不再複製最近 5 秒 Buffer，也不再重算已處理過的 Window。    """    # 只要網頁沒關閉、系統沒發出終止信號，這個 AI 主廚就會永久保持卡位、無限循環    while not state.stop_event.is_set():        try:            # 試圖從箱子裡拿出一包 0.5 秒的新資料（chunk），設定 timeout=0.5 秒，如果箱子是空的，最多只等 0.5 秒就跳出。            chunk = state.inference_queue.get(timeout=0.5,)        except queue.Empty:     # 如果等了 0.5 秒箱子還是空的（硬體還沒送料過來），就放棄這一輪，直接跳回 while 開頭繼續等            continue        try:            # 重連後在推論執行緒內安全重置，檢查剛剛的DAQ有沒有發出「重連信號」？            if state.need_stream_reset:                if state.streaming_engine is not None:                    # 正式命令串流引擎將內部累積的狀態、歷史特徵數據清空重置                    state.streaming_engine.reset()                                # 同步將跨批告警的滑動緩衝區（alarm_buffer）清空，避免新舊時間軸錯亂                state.alarm_buffer.clear()                 state.need_stream_reset = False     # 將重置信號降下來，改回 False                print("🔄 串流引擎已重置（重連）")                        # 安全防線：如果核心串流引擎根本沒組裝好，引爆異常、拒絕執行            if state.streaming_engine is None:                raise RuntimeError("StreamingRuntimeEngine 尚未初始化")            # ── 核心步驟 1：增量推論（只算這 0.5 秒新訊號） ──            #    將最新 0.5 秒的實體數據陣列丟進 StreamingEngine 進行增量分析            result = (                state.streaming_engine.process_chunk(                    ai0=chunk["ai0"],                    ai1=chunk["ai1"],                ))            # 訊號尚不足一個完整 Window 時，只累積狀態，不更新模型結果。            if result is None:                continue                        # ── 核心步驟 2：跨批告警與滑動歷史緩衝 ──            #    跨批告警（做法B）：本批新窗接進滑動緩衝，對整個緩衝重算            df_pred_new = result["df_predictions"]            state.alarm_buffer.extend(df_pred_new.to_dict("records"))                        # 滑動時間視窗裁剪：取得目前緩衝區最後面（最新）那一筆資料的時間 ref_t            latest_t = state.alarm_buffer[-1]["t_ref"]            # 嚴格實施工業法規：只要最前面（最舊）的資料，與最新資料的時間差超過了 ALARM_CONTEXT_SEC（10.0秒）            while state.alarm_buffer and (latest_t - state.alarm_buffer[0]["t_ref"]) > ALARM_CONTEXT_SEC:                # 就利用 popleft() 將左邊、最老舊的那一筆數據踢出緩衝區，永遠只保留最近 10.0 秒的所有預測                state.alarm_buffer.popleft()                        # 把這最近 10.0 秒的所有資料（包含前幾秒的上下文）重新還原成一個完整的 DataFrame            df_context = pd.DataFrame(list(state.alarm_buffer))            # 進行雙門檻 (Two-Stage)、最短時間、以及 Veto 否決權審查，算出最終的告警狀態            alarm_result = _run_alarm_postprocess(                df_context,                state.runtime_cfg,                state.model_bundle,            )            # ── 核心步驟 3：組裝即時健康監控指標 ──            #    把串流引擎的 buffer 狀態補進去            alarm_result["n_new_windows"] = result.get("n_new_windows", 0)      # 這一輪新增了幾個視窗            alarm_result["calc_time_sec"] = result.get("calc_time_sec", 0.0)    # 運算花了多久            alarm_result["is_demo"] = False                                     # 標記：這可不是 Demo，這是真的實體硬體推論！                        # 端到端延遲：            # captured_at 是 DAQ worker 把這批資料抓完、準備丟進 queue 的時間。            # 現在時間 - captured_at = 這批資料從「進 queue」到「模型推論完成」總共晚了幾秒。            latency_sec = time.time() - float(chunk.get("captured_at", time.time()))            alarm_result["latency_sec"] = round(latency_sec, 3)                        alarm_result["buffer_ready"] = state.streaming_engine.buffer_ready            alarm_result["buffer_sec_current"] = round(min(state.streaming_engine.elapsed_sec, STARTUP_WARMUP_SEC), 2)            alarm_result["buffer_sec_target"] = STARTUP_WARMUP_SEC                        # ============================================================            # 效能與即時性健康指標            # 目前是每 5 秒送入一批資料，因此以 DAQ 週期作為處理預算。            # ============================================================            calc_sec = float(result.get("calc_time_sec", 0.0))            processing_budget_sec = float(DAQ_LOOP_INTERVAL_SEC)                        # 估算處理工作是否逐漸累積。            # 計算時間小於 5 秒時，代表能在下一批資料進來前完成。            state.stream_lag_sec = max( 0.0, state.stream_lag_sec + calc_sec - processing_budget_sec,)            alarm_result["stream_lag_sec"] = round( state.stream_lag_sec, 3,)                        # latency_sec 包含 Queue 等待、模型計算與告警後處理，用它判斷本次結果是否在下一批資料進來前完成。            alarm_result["stream_realtime_ok"] = bool(latency_sec <= processing_budget_sec)            alarm_result["streaming_overrun"] = bool(state.streaming_overrun)                        # 呼叫出貨包裝線，將結果與實體波形（此處給 None 留空，因為 DAQ 工作執行緒已經幫我們更新過最新波形了）打包成 DetectResponse            response = _build_resp(alarm_result, ai0=None, ai1=None)            response_payload = response.dict()            # 拿鎖保護，將最終封裝好的 JSON 字典格式結果，同步塞進全域狀態的三個抽屜            with state.data_lock:                state.latest_inference_result = (response_payload)    # 供 /realtime/result API 隨時來拿最新答案                state.last_result = (response_payload)                state.history.append(response_payload)                # 記錄到歷史清單中                                # 超過 200 筆就除舊布新，扔掉最老的紀錄                if len(state.history) > 200:                    state.history.pop(0)                        # 在終端機印出增量推論完成的細節            if RUNTIME_VERBOSE:                print(                    "✅ 增量推論完成："                    f"新增Windows={result.get('n_new_windows', 0)}，"                    f"狀態={response.leak_status}，"                    f"計算={response.calc_time_sec}秒，"                    f"延遲={response_payload.get('latency_sec', 'NA')}秒，"                    f"qsize={state.inference_queue.qsize()}"                )        except Exception as exc:            # 如果 AI 計算、XGBoost 預測或法官判定有任何一行程式碼噴錯崩潰            traceback.print_exc()            print(f"❌ 增量推論失敗：{exc}")        finally:     # 無論成功還是失敗，都必須告訴 queue：「這批貨我確實處理完畢（銷案）了！」            state.inference_queue.task_done()                        # ============================================================# 啟動背景 DAQ 與模型工作# ============================================================def start_background_workers():    """啟動即時 DAQ 與串流推論背景工作。"""    # 檢查我們在一開始設定的硬體總開關（ENABLE_HARDWARE_DAQ）    # 如果當時設為 False（代表現在是 Mac、或是沒接擷取卡的離線狀態），卻有人硬要啟動實體監控，系統會立刻主動引爆錯誤（RuntimeError），拒絕往下執行，防範底層驅動程式崩潰。    if not ENABLE_HARDWARE_DAQ:        raise RuntimeError("實體 NI-DAQ 目前未啟用")    # 拿取「按鈕保護鎖」（worker_lock），防止使用者在網頁上因為網路延遲而「瘋狂連續點擊啟動」    with state.worker_lock:        # 如果全域狀態記錄著「其實現在已經在監控中」（True）        if state.monitoring_active:            print("ℹ️ 即時監控已經啟動")            return    # 任務結束，直接跳出（return），不重複開執行緒，避免多個員工同時抓硬體資料打架        # ── 舊 Session 狀態大掃除（除舊佈新） ──        # 清除上一輪的停止訊號（把 Event 燈號熄滅），準備迎接全新的全速運轉        state.stop_event.clear()        # 【清空排隊箱】把上一輪可能卡在排隊箱（inference_queue）裡、還沒被 AI 吃掉的舊資料全部強行倒掉，直到箱子完全空了（queue.Empty）才跳出迴圈。        while True:            try:                state.inference_queue.get_nowait()                state.inference_queue.task_done()            except queue.Empty:                break        # 新監控 Session 必須重新建立狀態:# 如果核心 AI 串流引擎已經存在，正式重置它內部所有的累積統計狀態（如 CUSUM 的累積值）        if state.streaming_engine is not None:            state.streaming_engine.reset()        state.alarm_buffer.clear()              # 將告警滑動緩衝區（最近 10 秒預測）清空歸零        state.stream_lag_sec = 0.0              # 將運算累積落後秒數歸零        state.streaming_overrun = False         # 將排隊箱爆滿的旗標初始化為 False        state.latest_inference_result = None    # 將最新的 AI 推論答案清空        # 如果 5 秒雙通道原始訊號不為空，把裡面殘留的舊電壓數據全部清空（clear）        if state.signal_buffer_ai0 is not None:            state.signal_buffer_ai0.clear()            state.signal_buffer_ai1.clear()                # 建立一個名叫 "daq-worker" 的獨立執行緒，指定它的工作目標是去執行 daq_worker 函式。        state.daq_thread = threading.Thread(            target=daq_worker,            name="daq-worker",            daemon=True,        # daemon=True 代表它是後台守護執行緒，只要 FastAPI 主程式關閉，這個員工就會跟著自動下班，不會卡在電腦記憶體裡。        )                # 建立一個名叫 "inference-worker" 的獨立執行緒，工作目標是去執行 inference_worker 函式。        state.inference_thread = threading.Thread(            target=inference_worker,            name="inference-worker",            daemon=True,        )        # 在狀態庫正式亮起綠燈，標記「即時監控目前正處於全速活躍狀態」        state.monitoring_active = True        # 【發動引擎】命令 DAQ 員工開始不眠不休地向實體硬體卡拔資料        state.daq_thread.start()        # 【發動引擎】命令 AI 員工開始在排隊箱另一頭待命、隨到隨算        state.inference_thread.start()    print("✅ 即時感測器監控已啟動")        # ============================================================# 停止函式# ============================================================def stop_background_workers():    """停止即時 DAQ 與串流推論。"""    # -- 第一階段：發出煞車訊號 -- 拿取按鈕保護鎖，防止使用者在網頁上瘋狂連續點擊「停止」    with state.worker_lock:        # 防呆機制：如果全域狀態顯示「本來就沒有在監控中」（False），就直接結束 return 離開        if not state.monitoring_active:            return        # 在狀態庫關閉綠燈，標記「即時監控目前已不再活躍」        state.monitoring_active = False        # ── 關鍵煞車信號 ──        # 還記得 daq_worker 與 inference_worker 的 while 迴圈條件是 while not state.stop_event.is_set() 嗎？        # 這裡按下 .set()，就像是在後台拉響下班警鈴，通知這兩個執行緒：「這一輪工作做完就到此為止，不准再貼下一輪迴圈了！」        state.stop_event.set()                # 把當前這兩個執行緒的指針暫存出來，準備等他們安全離開        daq_thread = state.daq_thread        inference_thread = state.inference_thread    # -- 第二階段 --：等待目前正在執行的擷取／推論離開。    for thread in (daq_thread, inference_thread,):    # 遍歷 DAQ 與 AI 推論這兩個執行緒        # 如果執行緒確實存在，而且「此時此刻還活著、還在把手邊最後工作收尾」        if (thread is not None and thread.is_alive()):            # 呼叫 .join(timeout=3.0) 意思是：「我等你 3 秒鐘，讓你把手頭上這最後 0.5 秒的資料讀完或算完，你算完安全退出了，我再繼續往下走。」            thread.join(timeout=3.0)    # 清除沒有處理完的資料。    # 排隊箱（inference_queue）裡可能還留著最後來不及算完的 Chunk 原料。    while True:        try:            # 利用 get_nowait() 無窮迴圈，在執行緒不在時強行把排隊箱完全倒乾淨，直到箱子全空            state.inference_queue.get_nowait()             state.inference_queue.task_done()        except queue.Empty:            break            # 拿交通警察鎖（data_lock），開始把記憶體裡的所有暫存欄位徹底擦洗歸零    with state.data_lock:        state.daq_thread = None                 # 銷毀 DAQ 執行緒指針        state.inference_thread = None           # 銷毀 AI 執行緒指針        state.latest_inference_result = None    # 清空最新答案                # 清空 5 秒原始訊號大水庫，把裡面的電壓數據全部清乾淨        if state.signal_buffer_ai0 is not None:            state.signal_buffer_ai0.clear()            state.signal_buffer_ai1.clear()        # 正式命令 AI 串流引擎把內部累積的所有 CUSUM 等時間特徵狀態徹底 Reset 歸零        if state.streaming_engine is not None:            state.streaming_engine.reset()        state.alarm_buffer.clear()         # 清空最近 10 秒預測緩衝區        state.stream_lag_sec = 0.0         # 累積落後秒數歸零        state.streaming_overrun = False    # 爆滿旗標恢復為 False    print("⏹ 即時感測器監控已停止")        # ============================================================# API關閉時，通知背景工作停止# ============================================================# 當在終端機按下 Ctrl+C 關閉 FastAPI 伺服器，或者關閉網頁服務時，FastAPI 會在死掉前一刻自動執行它@app.on_event("shutdown")def shutdown_runtime():    # 命令 DAQ 與 AI 執行緒立刻收尾下班、清空 Queue 大水庫、安全關閉 NI-DAQ 實體擷取卡    stop_background_workers()    print("⏹ API 已關閉")    # ============================================================# API Endpoints# ============================================================# 回傳模型狀態, 建立 API endpoint, 前端可以問：現在有哪些模型？@app.get("/models")      # 前端頁面載入時會呼叫這個，取得目前載入的模型名稱和版本，顯示在介面上的「XGBoost（雙感測器）」那個標籤。 def list_models():    # 回傳一個包有模型詳細規格的 JSON 清單（List）給前端網頁    return [{        "key": "xgb",                                                                                    # 模型的唯一識別代碼（這裡指 XGBoost）        "display_name": MODEL_DISPLAY_NAME,                                                              # 模型的中文顯示名稱（例如「H₂ 微洩漏智慧檢測模型」）        "is_available": state.ready,                                                                     # 告訴網頁模型現在準不準備好？（True/False），網頁據此決定按鈕要不要亮起        # ── 如果模型準備好了 (state.ready)，就去 runtime_cfg 查出正確參數回傳；還沒好就給 None ──        "threshold": state.runtime_cfg["window_threshold"] if state.ready else None,                     # 模型的判定分數門檻        "alarm_method": state.runtime_cfg["alarm_method"] if state.ready else None,                      # 告警採用的計分演算法（如 consecutive 等）        "consecutive": state.runtime_cfg["consecutive"] if state.ready else None,                        # 必須連續及格幾次才要爆警        "min_leak_duration_sec": state.runtime_cfg["min_leak_duration_sec"] if state.ready else None,    # 最短洩漏持續時間限制（秒）        "feature_count": len(state.model_bundle["feature_names"]) if state.ready else 0,                 # 算一下大腦（模型）當初訓練時吃了幾個特徵欄位，一併告訴前端做儀表板點檢顯示    }]# ============================================================# 做 DAQ 資料品質檢查# ============================================================def _validate_signal(signal: np.ndarray, name: str, n_samps: int):    # 如果實際點數少於預期的 90%, 就報錯    if len(signal) < n_samps * 0.9:        raise ValueError(f"{name}: 點數不足（期望 {n_samps}，實際 {len(signal)}）")    # 如果訊號全部都是 0：很可能接線有問題    if np.all(signal == 0):        raise ValueError(f"{name}: 訊號全為 0，請確認接線")    # 如果 RMS 太小，代表：sensor 可能沒通電或沒有有效訊號。    if np.sqrt(np.mean(signal ** 2)) < 1e-6:        raise ValueError(f"{name}: RMS 過低，感測器可能未通電")    # 檢查：NaN, Inf    if not np.isfinite(signal).all():        bad = int((~np.isfinite(signal)).sum())        raise ValueError(f"{name}: 含 {bad} 個 NaN/Inf，ADC 可能溢位")    # 計算訊號有多少比例接近, 如果超過 10% 點飽和，就報錯    clip = float(np.mean((signal >= DAQ_VOLT_MAX * 0.99) | (signal <= DAQ_VOLT_MIN * 0.99)))    # 如果 50 萬點裡面，有超過 10% 的點都卡在 ±10V 的極限邊緣（代表訊號被削頂、破音了）    if clip > 0.1:        # 這會導致 AI 模型遺失關鍵波形特徵，立刻提示工程師去調小放大器的增益（Gain）        raise ValueError(f"{name}: {clip*100:.1f}% 點飽和，請調整增益")# 手動 POST 一組 AI0 / AI1 array 進來，不是直接抓 DAQ@app.post("/detect")def detect(req: DetectRequest):    # 不論前端傳了什麼進來，直接無條件引爆 HTTP 503 (服務不可用) 的極限報錯！    raise HTTPException(        status_code=503,        detail=("/detect 在背景DAQ模式下暫停使用，請使用 /realtime 或 /predict/tdms"),    )# ============================================================# 啟動 DAQ 與串流推論# ============================================================# 建立一個 POST 路由，網址是 http://localhost:8000/monitor/start@app.post("/monitor/start")def start_monitor():    # 安全防線 1：檢查全域狀態裡的 state.ready（還記不記得開機 startup 時要特徵雙重比對？）    # 如果模型沒載入成功、或者 5 份設定檔有漏，這裡會是 False    if not state.ready:        raise HTTPException(status_code=503, detail="模型與 Runtime 尚未就緒",)    try:        # 安全點檢通過，正式呼叫上一輪學到的 start_background_workers() 函式，開始清除上一輪舊資料、大掃除、並正式喚醒 DAQ 與 AI 兩個執行緒        start_background_workers()    except Exception as exc:        # 【硬體異常攔截】：如果在啟動執行緒、或者呼叫實體卡時發生崩潰（例如 ENABLE_HARDWARE_DAQ 設為 False 踩到地雷）        raise HTTPException(status_code=500, detail=f"即時監控啟動失敗：{exc}",)    # 如果一切順利，打包一個成功的 JSON 字典回傳給前端網頁，前端收到後就會把介面的按鈕變成「監控中（亮綠燈）」    return {        "monitoring_active": True,        "message": "即時監控已啟動",    }# ============================================================# 停止監控並重置狀態# ============================================================# 建立一個 POST 路由，網址是 http://localhost:8000/monitor/stop@app.post("/monitor/stop")def stop_monitor():    # 直接呼 stop_background_workers()它會拉響下班警報 (stop_event.set())、溫和等待 3 秒鐘讓 NI-DAQ 卡安全收尾 (join)、並再次將 5 秒水庫與所有時間特徵統計值大掃除歸零    stop_background_workers()    # 熄火清洗完畢後，打包成功的 JSON 狀態回傳給前端網頁，前端收到後就會把網頁按鈕切回「已停止（亮紅燈/灰燈）」    return {        "monitoring_active": False,        "message": "即時監控已停止",    }# 【三種推論入口】# ============================================================# A.POST /realtime:回傳最新波形與模型結果# ============================================================# 建立一個 POST 路由，網址是 http://localhost:8000/realtime# 並且強制限制回傳的資料格式必須完全符合我們之前看過的 `DetectResponse` Pydantic 架構@app.post("/realtime", response_model=DetectResponse,)def realtime_detect():    """    回傳背景DAQ與背景模型的最新狀態。    本Endpoint不直接操作NI-DAQ，也不等待模型重新計算。    """    # 【安全防線 1】：檢查模型在開機時有沒有載入成功。如果沒載入成功，直接彈出 HTTP 503 拒絕服務    if not state.ready:        raise HTTPException(status_code=503, detail="正式模型尚未就緒")            # 【安全防線 2】：檢查使用者現在到底有沒有「按下啟動監控按鈕」？    # 如果背景兩個執行緒根本還沒開始運作（monitoring_active == False），前端就來要資料    if not state.monitoring_active:        # 立刻回傳 HTTP 409 (衝突錯誤)，告訴前端：「請先去啟動監控，不然我沒資料給你！」        raise HTTPException(status_code=409,detail="即時監控尚未啟動",)    # ── 快速取資料 ──    # 拿交通警察鎖（data_lock），確保在拷貝資料時，後台兩個執行緒不會同時進來修改資料導致寫入衝突    with state.data_lock:        # 1. 抓取（DAQ）剛剛做好的、瘦身成 2000 點的最新原始預覽波形字典        waveform = (dict(state.latest_waveform) if state.latest_waveform else {})        # 2. 抓取 AI 模型（XGBoost）剛剛算出、經過法官複審完畢的最新一輪告警結果        inference_result = (dict(state.latest_inference_result) if state.latest_inference_result else None)        # 3. 查一下目前的 5 秒訊號水庫裡，現在已經累積了多少點（samples）的數據        current_samples = (len(state.signal_buffer_ai0) if state.signal_buffer_ai0 is not None else 0)        # 4. 順便關心一下 DAQ 剛剛有沒有遇到硬體斷線或噴錯？        daq_error = state.daq_error    # 如果在倉庫裡發現 daq_error 欄位有寫字（代表硬體剛剛斷線或品管不及格）    if daq_error:        raise HTTPException(status_code=500, detail=(f"DAQ背景擷取失敗：{daq_error}"),)    # 從設定檔取得採樣率（如 100000 Hz）    fs = float(state.runtime_cfg["fs"])    # 換算目前大水庫已經累積了幾秒鐘的資料：【總點數 / 採樣率】    buffer_sec_current = min(current_samples / fs, RAW_BUFFER_SEC,)    # 確保算出來的秒數不會超過最大限制（5.0秒）    # ──「開機暖機中」應變方案 ──    # 因為剛按啟動時，硬體一瞬間就抓好波形了（waveform 有資料），但 AI 模型算特徵可能需要 0.05 秒，在 AI 模型「還沒交出這輩子第一筆答案」的這極短空檔內，inference_result 會是 None    # 模型尚未完成第一輪時，先回傳暖機狀態與最新波形。    if inference_result is None:        inference_result = {            "is_leak": False,           # 暖機中            "leak_status": "normal",    # 狀態為正常            "label": "暖機中",           # 網頁上的文字亮起「暖機中...」            "confidence": 0.0,            "score": 0.0,            "threshold": float(state.model_bundle["window_threshold"]),            "calc_time_sec": 0.0,            "timestamp": (datetime.now().strftime("%Y-%m-%d %H:%M:%S")),            "model_display_name": (MODEL_DISPLAY_NAME),            "is_demo": False,            "n_total_windows": 0,            "n_leak_windows": 0,            "n_disturbance_windows": 0,            "window_probas": None,            "buffer_ready": False,                               # 標記：水庫還沒完全存滿            "buffer_sec_current": round(buffer_sec_current,2,),  # 告訴網頁目前累積到幾秒了（例如 0.5 秒、1.0 秒...）            "buffer_sec_target": RAW_BUFFER_SEC,                 # 目標是 5.0 秒        }    # ── 網頁零延遲（解耦）──    # 波形永遠採用背景DAQ取得的最新版，不必等待模型完成。    inference_result.update(waveform)    # 用 ** 語法把這個融合了最新波形與最新 AI 答案的大禮包拆開，裝進標準出貨箱（DetectResponse）回傳給網頁前端    return DetectResponse(**inference_result)# ============================================================# B. POST /predict/tdms:分析完整 TDMS#       └── 上傳 TDMS 檔案 → 讀 ai0/ai1 → build_runtime_feature_table()#           → run_model_inference() → apply_postprocessing() → _build_resp()# ============================================================# 離線 TDMS 檢測 —— 完整走 build_runtime_feature_table（不受KNOWN LIMITATION 影響，因為是對整支已存在的檔案一次做完，不需要跨「擷取輪次」串接狀態）# 建立一個 POST 路由，網址是 http://localhost:8000/predict/tdms# 同樣嚴格限制回傳格式必須完全符合 `DetectResponse` Pydantic 架構@app.post("/predict/tdms", response_model=DetectResponse)async def predict_tdms(file: UploadFile = File(...)):        # 【安全防線 1：禁止多頭馬車】：檢查後台現在是不是「正在自動監控實體硬體」？    if state.monitoring_active:        # 如果正在監控，直接彈出 HTTP 409 (衝突錯誤)，無條件拒絕使用者上傳檔案！        # 這是為了防止「實體即時資料」與「上傳的歷史檔案」在記憶體裡搶奪 AI 模型導致狀態錯亂        raise HTTPException(status_code=409, detail=("目前正在進行即時監控，" "請先停止監控再分析 TDMS"),)            # 【安全防線 2：檢查副檔名】：只接受 TDMS 檔案，避免使用者頑皮上傳了 MP3、TXT、JPEG 等檔案    if not file.filename.lower().endswith(".tdms"):        raise HTTPException(400, "請上傳 .tdms 格式的檔案")    # 【讀取檔案】：將上傳的檔案二進位數據（bytes）一口氣讀進記憶體    file_bytes = await file.read()    print(f"📥 TDMS: {file.filename} ({len(file_bytes)/1024:.1f} KB)")        # 初始化暫存檔路徑與雙通道變數    tmp_path = None     # 暫時寫成一個 .tdms 檔案    # 先初始化，避免讀取失敗時變數不存在    ai0 = None    ai1 = None        try:        # ----------------------------------------------------        # 建立實體暫存檔        # ----------------------------------------------------        # FastAPI 收到的是 bytes，先寫成暫存 TDMS，供正式 Runtime 函式讀取。        with tempfile.NamedTemporaryFile(suffix=".tdms", delete=False) as tmp:            tmp.write(file_bytes)     # 把二進位數據寫進硬碟暫存檔            tmp_path = tmp.name       # 記下這個暫存檔在硬碟裡的實體路徑（例如 /tmp/tmp_xyz.tdms）                    # ----------------------------------------------------        # 讀取雙感測器原始訊號，供前端顯示波形        # ----------------------------------------------------        # 模型特徵仍由 build_runtime_feature_table()        # 正式建立，這裡讀取的 ai0/ai1 主要供預覽使用。        preview_record = load_one_tdms_record(            filepath=tmp_path,            fs_target=(float(state.runtime_cfg["fs"]) if state.ready else 1_000_000.0),        )        # 把遠端和近端感測器的實體電壓數據拷貝出來，準備等一下端給前端去瘦身、美顏畫圖        ai0 = preview_record["signal"]["ai0"]        ai1 = preview_record["signal"]["ai1"]        # 【安全防線 3】：再度點檢模型狀態。如果開機時設定檔不齊全、系統處於 Demo 模式        if not state.ready:            # 拒絕分析！因為這是正式檔案，既然要分析就要拿真大腦算，不允許用 Demo 隨機大輪盤去瞎猜            raise HTTPException(status_code=503, detail="正式模型與 Runtime 尚未就緒，無法分析 TDMS")        else:            # ── 正式啟動線下標準研發級特徵工程 ──            t0 = time.perf_counter()     # 啟動精準計時器            # 建立這一支檔案的 runtime file specification（規格說明書）            file_specs = build_runtime_file_specs([tmp_path])                        # 使用正式 Runtime 流程建立特徵，建立一個臨時資料夾作為分析期間的快取硬碟空間，用完會自動消失（防止記憶體塞爆）            with tempfile.TemporaryDirectory() as cache_dir:                # 建立特徵(把整支 TDMS 檔案內所有的訊號一次性吃完，切窗、轉頻譜、算基礎與進階特徵)                df_features = build_runtime_feature_table(                    file_specs=file_specs,                    runtime_cfg=state.runtime_cfg,                    cache_dir=cache_dir,                    split_name="api_predict_tdms",                    n_jobs=1,    # 單線程執行，避免多線程在後台搶 CPU                )            # ── 執行模型預測與推論 ──            # 把特徵表格丟進去讓 XGBoost 打分，並通過 Two-Stage 最短持續時間、Veto 否決權審查            result = run_inference_pipeline(df_features, state.runtime_cfg, state.model_bundle)            result["calc_time_sec"] = round(time.perf_counter() - t0, 3)     # 記錄整支檔案分析總共耗費了多少秒            result["is_demo"] = False                                        # 標記：這可是貨真價實的 AI 正式檔案診斷結果！                except Exception as e:        traceback.print_exc()         # 如果檔案格式毀損、或者內部特徵算到一半大崩潰，印出詳細紅字行數        raise HTTPException(500, f"TDMS 分析失敗: {e}")    finally:        # 不論成功或失敗，都刪除暫存 TDMS        if tmp_path and os.path.exists(tmp_path):            os.unlink(tmp_path)    # ── 包裝出貨與紀錄 ──    # 將 ai0、ai1 一起傳給 _build_resp，產生前端所需的波形預覽。    # 裡面會自動把這兩個陣列進行「等間隔抽樣 2000 點」與「濾波美顏處理」，組裝成最流暢的圖表大禮包    resp = _build_resp(result, ai0=ai0, ai1=ai1,)        # 保存 TDMS 來源與原始檔名    resp.source = "tdms"    resp.source_name = file.filename    # 記進後台的歷史清單中（最多留 200 筆）    _save_hist(resp)    return resp# ============================================================# 其他輔助端點# ============================================================# 讓前端查目前設定# 回傳目前的 runtime 設定，例如 window_sec、threshold、consecutive 等參數。# 前端可以用這個顯示「目前用什麼設定在跑」，或者 debug 時確認設定是否正確載入。@app.get("/cfg")     def get_cfg():    # 回傳目前系統運行的所有核心參數包（以字典 Dict 格式）    return {        "model": MODEL_DISPLAY_NAME,      # 模型在網頁上的中文名稱        "model_id": MODEL_ID,             # 模型的流水號 ID                # ── 【三元運算子防崩潰】模型特徵清單。好了解決先前 Undefined 報錯的欄位都記錄在這裡 ──        "model_feature_names": (state.model_bundle["feature_names"] if state.ready else []),        "runtime_schema_path": (RUNTIME_FEATURE_SCHEMA_PATH),      # 設定檔在硬碟的實體路徑                "is_available": state.ready,                                                                          # AI 大腦目前是否可用:# 「後端推論管線（Inference Pipeline）與 AI 模型權重是否已成功初始化並載入記憶體」        "window_sec": state.runtime_cfg["window_sec"] if state.ready else None,                               # 特徵切窗秒數        "hop_sec": state.runtime_cfg["hop_sec"] if state.ready else None,                                     # 視窗移動步長秒數        "daq_capture_sec": DAQ_CAPTURE_SEC,                                                                   # 每次硬體擷取長度（0.5 秒）        "daq_loop_interval_sec": DAQ_LOOP_INTERVAL_SEC,        "buffer_sec": RAW_BUFFER_SEC,                                                                         # 歷史大水庫長度（5.0 秒）        "window_threshold": (state.model_bundle["window_threshold"] if state.ready else None),                # 模型判定門檻        "alarm_method": state.runtime_cfg["alarm_method"] if state.ready else None,                           # 告警判定演算法        "consecutive": (state.runtime_cfg.get("consecutive") if state.ready else None),                       # 連續及格次數限制        "min_leak_duration_sec": (state.runtime_cfg.get("min_leak_duration_sec") if state.ready else None),   # 最短洩漏時間        "smooth_window": (state.runtime_cfg.get("smooth_window") if state.ready else None),                   # 滑動平滑窗大小        "use_veto": (state.runtime_cfg.get("use_veto") if state.ready else None),                             # 是否啟用雜訊否決權        "sensor_mode": "two_sensor (ai0=far, ai1=near)",                                                      # 標記：目前是專業雙感測器模式        "last_update": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),                                          # 點檢時的伺服器目前時間    }# 讓前端查系統狀態# 回傳系統是否準備好（ready: true/false）、是不是 Demo 模式。前端頁面載入時會先打這個，決定要顯示「正常模式」還是「Demo 模式（無法連線後端）」的標籤。@app.get("/status")def get_status():    return {        "ready": state.ready,        # 「後端推論管線（Inference Pipeline）與 AI 模型權重是否已成功初始化並載入記憶體」        "last_detection": state.last_result["timestamp"] if state.last_result else None,    # 上一次算完答案的時間戳        "total_detections": len(state.history),     # 開機到現在，系統總共成功推論了幾批資料    }# 清除歷史紀錄@app.post("/clear")def clear_data():    # 拿交通警察鎖（data_lock），強制將全域狀態內累積的成果、歷史、大水庫、CUSUM 狀態徹底擦洗歸零    with state.data_lock:        state.last_result = None                     state.latest_inference_result = None        state.history.clear()                          # 清空 Log 歷史小帳本        if state.signal_buffer_ai0 is not None:            state.signal_buffer_ai0.clear()            # 清空 ai0 原始訊號大水庫            state.signal_buffer_ai1.clear()            # 清空 ai1 原始訊號大水庫        if state.streaming_engine is not None:            state.streaming_engine.reset()             # 重置 AI 串流引擎內部的時序統計狀態        state.streaming_overrun = False                # 爆滿故障燈歸零        state.alarm_buffer.clear()                     # 清空最近 10 秒跨批告警緩衝    # 清除尚未處理的 DAQ 批次，強制把排隊箱徹底清空。    while True:        try:            state.inference_queue.get_nowait()            state.inference_queue.task_done()        except queue.Empty:            break            # 回傳大掃除成功的時間與喜報給前端    return {        "message": "波形、推論與串流狀態已清除",        "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),        }# 回傳歷史結果:取得最近 N 筆的歷史紀錄，前端用來顯示 Log 區塊（你介面下方那個表格）。@app.get("/history")def get_history(limit: int = 50):    # 利用 Python 的切片語法 [-limit:]，如果你只要 50 筆，它就從歷史清單尾端截取最新的 50 筆 JSON 紀錄丟回去    return {"records": state.history[-limit:], "total": len(state.history)}# 最簡單的 API health/info endpoint@app.get("/api")def root():    # 當操作人員直接在網址輸入 http://localhost:8000/api 時，會看到這行簡單的問候與文檔指引路徑    return {"message": "H₂ 洩漏檢測 API v5.0（雙感測器）", "docs": "/docs", "ready": state.ready}# 直接提供你的前端 HTML@app.get("/hydrogenhmi.html")def serve_html():    # 組合出前端 HTML 檔案在硬碟中的精準路徑    html_path = os.path.join(BASE_DIR, "hydrogenhmi.html")    # 如果網頁檔案真的在同一個資料夾內    if os.path.exists(html_path):        # 利用 FastAPI 內建的 FileResponse，直接把這個 HTML 網頁「整支派發出去」在瀏覽器上開啟        return FileResponse(html_path)    raise HTTPException(404, "找不到 hydrogenhmi.html，請確認檔案在同一資料夾")# ============================================================# 啟動# ============================================================if __name__ == "__main__":    import uvicorn    print("=" * 60)    print("H₂ 微洩漏智慧檢測系統 API 伺服器 v5.0（雙感測器）")    print("=" * 60)    print(f"ai0 (far)  : {DAQ_CHANNEL_AI0}")    print(f"ai1 (near) : {DAQ_CHANNEL_AI1}")    print(f"DAQ_CAPTURE_SEC = {DAQ_CAPTURE_SEC}s")    print(f"DAQ_LOOP_INTERVAL_SEC = {DAQ_LOOP_INTERVAL_SEC}s")    print(        f"推論取樣策略：每 {DAQ_LOOP_INTERVAL_SEC:.1f} 秒抓 "        f"{DAQ_CAPTURE_SEC:.1f} 秒資料進行一次推論"    )    print("API 文件：http://localhost:8000/docs")    print("前端介面：http://localhost:8000/hydrogenhmi.html")    print("=" * 60)    uvicorn.run(app, host="0.0.0.0", port=8000, reload=False, access_log=False,)    '''整個流程             DAQ              │              │ 每次抓 0.5 sec              ▼       ┌──────────────┐       │ 0.5 sec 新資料 │       └──────────────┘              │              ▼        加入 5 sec buffer              │              ▼       ┌──────────────┐       │ 最近最多 5 sec│       └──────────────┘              │              ▼       Sliding Windows       window_sec / hop_sec              │              ▼       Feature Engineering              │              ▼           XGBoost              │              ▼        Alarm / Postprocess              │              ▼       normal / disturbance / leak'''